begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into public.calendar_event_colors(value) values ('BLUE'),('PURPLE'),('GREEN') on conflict do nothing;
insert into auth.users(id) values('00000000-0000-4000-8000-000000008811'),('00000000-0000-4000-8000-000000008812');
insert into public.users(id) values('00000000-0000-4000-8000-000000008811'),('00000000-0000-4000-8000-000000008812') on conflict do nothing;
insert into public.workspaces(id,name,personal,creator_id) values('00000000-0000-0000-0000-000000000000','Desktop admission fixture',false,'00000000-0000-4000-8000-000000008811') on conflict(id) do update set creator_id=excluded.creator_id;
insert into public.workspace_members(ws_id,user_id,type) values('00000000-0000-0000-0000-000000000000','00000000-0000-4000-8000-000000008811','MEMBER') on conflict do nothing;
select ok(not has_function_privilege('authenticated','private.desktop_deployment_set_delivery(uuid,text,bigint,boolean,uuid,bigint,timestamptz,timestamptz)','EXECUTE'),'authenticated cannot execute platform control');
select ok(not has_function_privilege('anon','private.desktop_deployment_set_delivery(uuid,text,bigint,boolean,uuid,bigint,timestamptz,timestamptz)','EXECUTE'),'anonymous cannot execute platform control');
select throws_ok($$select private.desktop_deployment_set_delivery(null,'windows',0,false)$$,'42501','desktop_vault_forbidden','missing actor denied');
select throws_ok($$select private.desktop_deployment_set_delivery('00000000-0000-4000-8000-000000008812','windows',0,false)$$,'42501','desktop_vault_forbidden','nonmember denied');
insert into public.workspace_members(ws_id,user_id,type) values('00000000-0000-0000-0000-000000000000','00000000-0000-4000-8000-000000008812','MEMBER');
update public.workspace_default_permissions set enabled=false where ws_id='00000000-0000-0000-0000-000000000000';
select throws_ok($$select private.desktop_deployment_set_delivery('00000000-0000-4000-8000-000000008812','windows',0,false)$$,'42501','desktop_vault_forbidden','member without permission denied');
select throws_ok($$select private.desktop_deployment_set_delivery('00000000-0000-4000-8000-000000008811','linux',0,false)$$,'22023','desktop_admission_invalid','Linux admission excluded');
select is((select revision from private.desktop_deployment_environments where platform='windows'),0::bigint,'platform starts epoch zero');
select throws_ok($$select private.desktop_deployment_set_delivery('00000000-0000-4000-8000-000000008811','windows',0,true)$$,'40001','desktop_version_not_ready','no active version cannot enable');
create temp table admission_version as select value.* from private.desktop_deployment_create_version('00000000-0000-4000-8000-000000008811','windows','fixture-encrypted-key') value;
select throws_ok($$select private.desktop_deployment_set_delivery('00000000-0000-4000-8000-000000008811','windows',0,true,(select id from admission_version),1,clock_timestamp(),clock_timestamp()+interval '1 day')$$,'40001','desktop_version_not_ready','draft never enables');
select private.desktop_deployment_write_resource('00000000-0000-4000-8000-000000008811',(select id from admission_version),1,'windows_authenticode_certificate_pfx','fixture-pfx',repeat('a',64),32);
select private.desktop_deployment_write_resource('00000000-0000-4000-8000-000000008811',(select id from admission_version),2,'WINDOWS_SIGNING_CERTIFICATE_PASSWORD','fixture-password',repeat('b',64),4);
select private.desktop_deployment_validate_version('00000000-0000-4000-8000-000000008811',(select id from admission_version),3,'{}');
select private.desktop_deployment_activate_version('00000000-0000-4000-8000-000000008811',(select id from admission_version),3);
select is((select revision from private.desktop_deployment_environments where platform='windows'),1::bigint,'activation advances admission epoch but stays disabled');
select is((select enabled from private.desktop_deployment_environments where platform='windows'),false,'activation does not enable');
select throws_ok($$select private.desktop_deployment_set_delivery('00000000-0000-4000-8000-000000008811','windows',0,true,(select id from admission_version),3,clock_timestamp(),clock_timestamp()+interval '1 day')$$,'40001','desktop_environment_conflict','stale environment revision denied');
select throws_ok($$select private.desktop_deployment_set_delivery('00000000-0000-4000-8000-000000008811','windows',1,true,(select id from admission_version),2,clock_timestamp(),clock_timestamp()+interval '1 day')$$,'40001','desktop_version_not_ready','stale material revision denied');
select throws_ok($$select private.desktop_deployment_set_delivery('00000000-0000-4000-8000-000000008811','macos',0,true,(select id from admission_version),3,clock_timestamp(),clock_timestamp()+interval '1 day')$$,'40001','desktop_version_not_ready','cross-platform active identity denied');
select throws_ok($$select private.desktop_deployment_set_delivery('00000000-0000-4000-8000-000000008811','windows',1,true,(select id from admission_version),3,null,clock_timestamp()+interval '1 day')$$,'40001','desktop_material_not_ready','fresh receipt required');
select throws_ok($$select private.desktop_deployment_set_delivery('00000000-0000-4000-8000-000000008811','windows',1,true,(select id from admission_version),3,clock_timestamp()-interval '31 seconds',clock_timestamp()+interval '1 day')$$,'40001','desktop_material_not_ready','old receipt denied');
select throws_ok($$select private.desktop_deployment_set_delivery('00000000-0000-4000-8000-000000008811','windows',1,true,(select id from admission_version),3,clock_timestamp()+interval '6 seconds',clock_timestamp()+interval '1 day')$$,'40001','desktop_material_not_ready','future fabricated receipt denied');
select throws_ok($$select private.desktop_deployment_set_delivery('00000000-0000-4000-8000-000000008811','windows',1,true,(select id from admission_version),3,clock_timestamp(),clock_timestamp()-interval '1 second')$$,'40001','desktop_material_not_ready','expired material denied');
select is((select count(*)::integer from private.desktop_deployment_audit_events where event_type like 'environment.%'),0,'rejected controls create no misleading audit');
select lives_ok($$select private.desktop_deployment_set_delivery('00000000-0000-4000-8000-000000008811','windows',1,true,(select id from admission_version),3,clock_timestamp(),clock_timestamp()+interval '1 day')$$,'fresh validated active version enables');
select is((select revision from private.desktop_deployment_environments where platform='windows'),2::bigint,'enable increments epoch');
select is((select enabled from private.desktop_deployment_environments where platform='macos'),false,'Windows enable never enables macOS');
select is((select count(*)::integer from private.desktop_deployment_audit_events where event_type='environment.enabled' and actor_id='00000000-0000-4000-8000-000000008811'),1,'enabled audit stamps exact actor');
create temp table admission_token as select value.* from private.desktop_deployment_create_token('00000000-0000-4000-8000-000000008811',(select id from admission_version),'Fixture','ttr_desktop_ci_admission',repeat('c',64),now()+interval '1 day') value;
create temp table before_disable as select value.* from private.desktop_deployment_reserve_bundle((select id from admission_token),'windows','101','1',repeat('a',40)) value;
select is((select delivery_revision from before_disable),2::bigint,'reservation captures environment epoch');
select lives_ok($$select private.desktop_deployment_set_delivery('00000000-0000-4000-8000-000000008811','windows',2,false)$$,'disable requires no material');
select throws_ok($$select private.desktop_deployment_complete_bundle((select id from before_disable))$$,'42501','desktop_bundle_denied','disable after reservation blocks completion');
select throws_ok($$select private.desktop_deployment_reserve_bundle((select id from admission_token),'windows','101','2',repeat('a',40))$$,'42501','desktop_bundle_denied','disable blocks new reservation');
select throws_ok($$select private.desktop_deployment_set_delivery('00000000-0000-4000-8000-000000008811','windows',2,true,(select id from admission_version),3,clock_timestamp(),clock_timestamp()+interval '1 day')$$,'40001','desktop_environment_conflict','stale enable cannot undo newer disable');
select lives_ok($$select private.desktop_deployment_set_delivery('00000000-0000-4000-8000-000000008811','windows',3,true,(select id from admission_version),3,clock_timestamp(),clock_timestamp()+interval '1 day')$$,'new enable receives a fresh epoch');
select throws_ok($$select private.desktop_deployment_complete_bundle((select id from before_disable))$$,'42501','desktop_bundle_denied','disable/re-enable cannot revive old reserved lease');
select lives_ok($$select private.desktop_deployment_complete_bundle((select id from before_disable),'admission_changed')$$,'old lease can be safely consumed as failed');
create temp table after_enable as select value.* from private.desktop_deployment_reserve_bundle((select id from admission_token),'windows','101','2',repeat('a',40)) value;
select is((select delivery_revision from after_enable),4::bigint,'new attempt captures new epoch');
select lives_ok($$select private.desktop_deployment_complete_bundle((select id from after_enable))$$,'new reservation may deliver');
-- A pre-migration reservation has default -1 and must never become deliverable.
create temp table legacy_admission as select value.* from private.desktop_deployment_reserve_bundle((select id from admission_token),'windows','101','4',repeat('a',40)) value;
update private.desktop_deployment_fetch_leases set delivery_revision=-1 where id=(select id from legacy_admission);
select throws_ok($$select private.desktop_deployment_complete_bundle((select id from legacy_admission))$$,'42501','desktop_bundle_denied','legacy minus-one lease remains permanently denied');
select lives_ok($$select private.desktop_deployment_complete_bundle((select id from legacy_admission),'legacy_admission')$$,'legacy lease may be safely failed');
create temp table revoked_admission as select value.* from private.desktop_deployment_reserve_bundle((select id from admission_token),'windows','101','3',repeat('a',40)) value;
select private.desktop_deployment_revoke_token('00000000-0000-4000-8000-000000008811',(select id from admission_token));
select throws_ok($$select private.desktop_deployment_complete_bundle((select id from revoked_admission))$$,'42501','desktop_bundle_denied','token revocation remains final-live guard');
select lives_ok($$select private.desktop_deployment_set_delivery('00000000-0000-4000-8000-000000008811','windows',4,false)$$,'revoked token does not prevent emergency disable');
select is((select count(*)::integer from private.desktop_deployment_audit_events where event_type='environment.disabled'),2,'each successful disable is audited');
select is((select revision from private.desktop_deployment_environments where platform='windows'),5::bigint,'disable monotonic epoch retained');
select throws_ok($$select private.desktop_deployment_set_delivery('00000000-0000-4000-8000-000000008811','windows',5,false,(select id from admission_version))$$,'22023','desktop_admission_invalid','disable does not accept fabricated material fields');
select is((select revision from private.desktop_deployment_environments where platform='windows'),5::bigint,'failed control rolls back epoch');
select lives_ok($$select private.desktop_deployment_set_delivery('00000000-0000-4000-8000-000000008811','macos',0,false)$$,'unconfigured platform may remain safely disabled');
select is((select revision from private.desktop_deployment_environments where platform='macos'),1::bigint,'disable of unchanged state still fences older intent');
select * from finish();
rollback;
